      <ListState :loading="loading" :error="error" :has-data="materials.length>0" empty-text="还没有参考物料" @retry="loadMaterials"><el-table :data="materials" row-key="id"><el-table-column prop="title" label="标题" min-width="200"/><el-table-column prop="sourceName" label="来源" width="160"/><el-table-column label="操作" width="160"><template #default="{row}"><el-button v-if="row.canWrite" link type="primary" @click="openEditMaterial(row)">编辑</el-button></template></el-table-column><el-table-column prop="kind" label="类型" width="120"/><el-table-column label="内容" min-width="260"><template #default="{row}">{{truncate(row.excerpt||row.insight)}}</template></el-table-column><el-table-column label="链接" width="160"><template #default="{row}"><a v-if="row.url" :href="row.url" target="_blank" rel="noopener noreferrer">打开</a><el-button v-if="row.canWrite" link type="danger" @click.stop="removeMaterial(row.id)">移入回收站</el-button></template></el-table-column><el-table-column label="附件" min-width="220"><template #default="{row}"><div v-for="attachment in row.attachments" :key="attachment.id"><el-button link type="primary" @click="api.downloadAttachment(attachment.id,attachment.name)">{{attachment.name}}</el-button><el-button v-if="row.canWrite" link type="danger" @click="removeAttachment(attachment.id)">移除</el-button></div><el-upload v-if="row.canWrite" :show-file-list="false" :http-request="({file}:any)=>uploadMaterial(row.id,file)"><el-button link type="primary">上传附件</el-button></el-upload></template></el-table-column></el-table></ListState>
