 type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" :disabled="!canEditCurrent || !!detail.idea.archivedAt"/></el-form-item><el-form-item label="结论"><el-input v-model="detail.idea.conclusion" type="textarea" :rows="3" :disabled="!canEditCurrent || !!detail.idea.archivedAt"/></el-form-item><el-form-item label="可见范围"><el-radio-group v-model="detail.idea.visibility" :disabled="!canEditCurrent || !!detail.idea.archivedAt"><el-radio value="private">仅自己</el-radio><el-radio value="shared">共享</el-radio></el-radio-group></el-form-item><el-button v-if="canEditCurrent && !detail.idea.archivedAt" type="primary" @click="saveDetail">保存修改</el-button></el-form><el-divider/><h3>子创意</h3><div v-for="child in detail.children" :key="child.id" class="idea-row" @click="openIdea(child.id)">{{child.title}} <el-tag size="small">{{statusName[child.status]}}</el-tag></div></el-tab-pane>
        <el-tab-pane label="参考物料"><el-button v-if="canEditCurrent && !detail.idea.archivedAt" @click="openLinkMaterial">关联物料</el-button><el-empty v-if="!detail.materials.length" description="尚未关联参考物料"/><el-card v-for="m in detail.materials" :key="m.id" shadow="never" class="sub-card"><b>{{m.title}}</b><el-button v-if="canEditCurrent && !detail.idea.archivedAt" link type="danger" @click="unlinkMaterial(m.id)">解除关联</el-button><div v-for="attachment in m.attachments" :key="attachment.id"><el-button link type="primary" @click="api.downloadAttachment(attachment.id,attachment.name)">{{attachment.name}}</el-button><el-button v-if="m.canWrite" link type="danger" @click="removeAttachment(attachment.id)">移除</el-button></div><p>{{m.excerpt}}</p><p class="muted">{{m.insight || m.linkInsight}} <a v-if="m.url" :href="m.url" target="_blank" rel="noopener noreferrer">打开来源</a></p></el-card></el-tab-pane>
        <el-tab-pane label="实践与时间线"><el-button v-if="canEditCurrent && !detail.idea.archivedAt" type="primary" @click="editingPracticeId=undefined;practiceVisible=true">记录实践</el-button><el-timeline class="timeline"><el-timeline-item v-for="item in detail.timeline" :key="item.id" :timestamp="dateText(item.createdAt)" :type="item.type==='practice'?'primary':'info'"><template v-if="item.type==='practice'"><b>{{item.practice?.title||practiceType[item.practice?.kind||'']||'实践记录'}}</b><p>{{item.practice?.action}}</p><p v-if="item.practice?.result">结果：{{item.practice.result}}</p><p v-if="item.practice?.nextAction">下一步：{{item.practice.nextAction}}</p><p v-if="item.practice?.minutes || item.practice?.cost">投入：{{item.practice.minutes || 0}} 分钟 · {{item.practice.cost || 0}} 元</p><el-button v-if="canEditCurrent" link type="primary" @click="editPractice(item.practice!)">编辑</el-button><el-button v-if="canEditCurrent" link type="danger" @click="removePractice(item.id)">删除</el-button><el-tag v-for="(metric,i) in item.practice?.metrics" :key="i" size="small" class="tag">{{metric.name}}：{{metric.value}} {{metric.unit}}</el-tag></template><span v-else>{{eventName[item.eventType||'']||item.eventType}}</span></el-timeline-item></el-timeline><el-empty v-if="!detail.practices.length&&!detail.events.length" description="记录一次小实践，留下结果和下一步"/></el-tab-pane>
        <el-tab-pane label="关联创意"><el-button v-if="canEditCurrent && !detail.idea.archivedAt" @click="relateCurrent">关联已有创意</el-button><div v-for="item in detail.related" :key="item.id" class="idea-row"><span @click="openIdea(item.id)">{{item.title}}</span><el-button v-if="canEditCurrent" link type="danger" @click="unlinkRelation(item.id)">解除关联</el-button></div></el-tab-pane></el-tabs>
      </template>
    </el-drawer>

    <el-dialog v-model="practiceVisible" title="记录实践" width="700px"><el-form label-width="90px"><el-form-item label="标题"><el-input v-model="practiceForm.title"/></el-form-item><el-form-item label="类型"><el-select v-model="practiceForm.kind"><el-option v-for="(label,key) in practiceType" :key="key" :label="label" :value="key"/></el-select></el-form-item><el-form-item label="做了什么"><el-input v-model="practiceForm.action" type="textarea" :rows="3"/></el-form-item><el-form-item label="预期"><el-input v-model="practiceForm.expectation"/></el-form-item><el-form-item label="结果"><el-input v-model="practiceForm.result" type="textarea" :rows="3"/></el-form-item><el-form-item label="投入"><div class="metric-line"><el-input-number v-model="practiceForm.minutes" :min="0" placeholder="分钟"/><el-input-number v-model="practiceForm.cost" :min="0" :precision="2" placeholder="费用"/></div></el-form-item><el-form-item label="成果链接"><el-input v-model="practiceForm.resultUrl" placeholder="可选：https://"/></el-form-item><el-form-item label="判断"><el-select v-model="practiceForm.decision" clearable><el-option label="继续" value="continue"/><el-option label="调整" value="adjust"/><el-option label="停止" value="stop"/></el-select></el-form-item><el-form-item label="指标"><div v-for="(metric,i) in practiceForm.metrics" :key="i" class="metric-line"><el-input v-model="metric.name" placeholder="指标"/><el-input-number v-model="metric.value" placeholder="数值"/><el-input v-model="metric.unit" placeholder="单位"/><el-button link type="danger" @click="practiceForm.metrics.splice(i,1)">移除</el-button></div><el-button link type="primary" @click="practiceForm.metrics.push({name:'',value:0,unit:''})">添加指标</el-button></el-form-item><el-form-item label="下一步"><el-input v-model="practiceForm.nextAction"/></el-form-item><el-form-item label="同步主记录"><el-switch v-model="practiceForm.updateNextAction"/></el-form-item></el-form><template #footer><el-button @click="practiceVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="savePractice">保存实践</el-button></template></el-dialog>
    <el-dialog v-model="linkIdeaVisible" title="关联已有创意"><el-select v-model="selectedIdea" filterable placeholder="选择创意"><el-option v-for="item in ideas.filter(x=>x.id!==detail?.idea.id)" :key="item.id" :label="item.title" :value="item.id"/></el-select><template #footer><el-button @click="linkIdeaVisible=false">取消</el-button><el-button type="primary" @click="confirmRelation">关联</el-button></template></el-dialog>
