<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import PageShell from '@/components/PageShell.vue'
import ListState from '@/components/ListState.vue'
import { useAuthStore } from '@/stores/auth'
import * as api from '@/api/creative'
import type { Idea, Detail, Material, IdeaStatus } from '@/api/creative'
const route=useRoute(),router=useRouter(),auth=useAuthStore()
const canWrite=computed(()=>auth.isSuperAdmin||auth.permissions.includes('creative:write')||auth.permissions.includes('*'))
const canEditCurrent=computed(()=>canWrite.value&&!!detail.value?.canWrite)
const isWorkbench=computed(()=>route.path==='/creative'),isIdeas=computed(()=>route.path==='/creative/ideas'),isMaterials=computed(()=>route.path==='/creative/materials')
const pageTitle=computed(()=>isWorkbench.value?'创意工作台':isIdeas.value?'创意库':isMaterials.value?'参考物料':route.path.endsWith('recycle-bin')?'创意回收站':'创意平台')
const typeName:Record<string,string>={unclassified:'未分类',quick_idea:'随手想法',project:'项目方向',series:'内容系列',content_topic:'内容选题',product_feature:'产品功能',method:'实践方法'}
const statusName:Record<string,string>={inbox:'灵感箱',to_validate:'待验证',in_progress:'实践中',settled:'已沉淀',paused:'已搁置'}
const practiceType:Record<string,string>={research:'研究',production:'制作',test:'测试',publish:'发布',review:'复盘'}
const eventName:Record<string,string>={created:'创建创意',updated:'更新创意',status_changed:'状态变更',archived:'归档创意',restored:'恢复创意',restored_from_archive:'取消归档',deleted:'移入回收站',practice_added:'记录实践',material_linked:'关联物料',material_unlinked:'解除物料关联',related:'关联创意'}
const loading=ref(false),saving=ref(false),error=ref(''),ideas=ref<Idea[]>([]),materials=ref<Material[]>([]),total=ref(0),detailTagsText=ref('')
const overviewData=ref<Record<string,any>>(),detail=ref<Detail>(),recycle=ref<{ideas:Idea[];materials:Material[]}>()
const query=reactive({q:String(route.query.q||''),status:String(route.query.status||''),ideaType:String(route.query.ideaType||''),tag:String(route.query.tag||''),starred:route.query.starred==='true',archived:route.query.archived==='true',page:Number(route.query.page||1),pageSize:Number(route.query.pageSize||20)})
const availableTags=ref<Array<{id:string;name:string}>>([])
const viewMode=ref<'table'|'board'>('table'),editingPracticeId=ref<string|undefined>()
const materialQuery=reactive({q:''}),captureVisible=ref(false),captureText=ref(''),captureUrl=ref(''),createVisible=ref(false),detailVisible=ref(false),practiceVisible=ref(false),showMaterialForm=ref(false),linkVisible=ref(false),selectedMaterial=ref(''),recycleTab=ref('ideas'),selectedIdea=ref('')
const form=reactive({title:'',originalText:'',description:'',ideaType:'unclassified',tagsText:'',parentId:'',nextAction:'',visibility:'private'})
const generatedTemplate=ref('')
const materialForm=reactive({kind:'note',title:'',sourceName:'',author:'',url:'',excerpt:'',insight:'',visibility:'private',version:1})
const editingMaterialId=ref<string>()
const practiceForm=reactive({kind:'research',title:'',action:'',expectation:'',result:'',decision:'',nextAction:'',minutes:undefined as number|undefined,cost:undefined as number|undefined,resultUrl:'',metrics:[] as Array<{name:string;value:number;unit:string}>,updateNextAction:false})
const parentOptions=computed(()=>ideas.value.filter(x=>x.id!==detail.value?.idea.id))
function truncate(s:string){return (s||'').slice(0,90)}function dateText(s?:string|null){return s?new Date(s).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'未安排'}
async function load(){loading.value=true;error.value='';try{availableTags.value=await api.listTags();if(isWorkbench.value)overviewData.value=await api.overview();else if(isIdeas.value)await loadIdeas();else if(isMaterials.value)await loadMaterials();else if(route.path.endsWith('recycle-bin'))recycle.value=await api.recycleBin();else if(route.params.id)await openIdea(String(route.params.id))}catch(e){error.value=e instanceof Error?e.message:'加载失败'}finally{loading.value=false}}
async function loadIdeas(){const res=await api.listIdeas({...query,tag:query.tag||undefined,starred:query.starred?true:undefined});ideas.value=res.items;total.value=res.total}
async function loadMaterials(){const res=await api.listMaterials(materialQuery);materials.value=res.items}
function goIdeas(status=''){router.push({path:'/creative/ideas',query:status?{status}:undefined})}
function applyIdeaTemplate(type:string){const prompts:Record<string,string>={project:'## 想解决的问题\n\n## 目标人群\n\n## 目标结果\n\n## 最小验证\n\n## 停止条件\n',series:'## 面向谁\n\n## 核心承诺\n\n## 固定结构\n\n## 首批选题\n',content_topic:'## 受众痛点\n\n## 开头钩子\n\n## 核心观点\n\n## 表达形式\n\n## 验证方式\n',product_feature:'## 使用场景\n\n## 当前困难\n\n## 方案与价值\n\n## 最小范围\n',method:'## 假设\n\n## 实施步骤\n\n## 观察方式\n\n## 适用边界\n'};if(!form.description.trim()||form.description===generatedTemplate.value){form.description=prompts[type]||'';generatedTemplate.value=form.description}}
function openCreate(){form.title='';form.originalText='';form.ideaType='unclassified';form.description='';generatedTemplate.value='';applyIdeaTemplate(form.ideaType);form.tagsText='';form.parentId='';form.nextAction='';form.visibility='private';loadIdeas();createVisible.value=true}
async function saveIdea(){saving.value=true;try{const item=await api.createIdea({title:form.title,originalText:form.originalText,description:form.description,ideaType:form.ideaType,tagNames:form.tagsText.split(/[,，]/).map(x=>x.trim()).filter(Boolean),parentId:form.parentId||null,nextAction:form.nextAction,visibility:form.visibility});createVisible.value=false;ElMessage.success('创意已保存');await loadIdeas();availableTags.value=await api.listTags();openIdea(item.id)}catch(e){ElMessage.error(e instanceof Error?e.message:'保存失败')}finally{saving.value=false}}
async function saveCapture(){if(!captureText.value.trim()&&!captureUrl.value.trim()){ElMessage.warning('请输入想法或参考链接');return}saving.value=true;try{const item=await api.capture(captureText.value,'',captureUrl.value,crypto.randomUUID());captureVisible.value=false;captureText.value='';captureUrl.value='';ElMessage.success('灵感已记录');if(isWorkbench.value)overviewData.value=await api.overview();openIdea(item.id)}catch(e){ElMessage.error(e instanceof Error?e.message:'记录失败')}finally{saving.value=false}}
function captureKey(e:KeyboardEvent){if((e.metaKey||e.ctrlKey)&&e.key==='Enter'&&!e.isComposing){e.preventDefault();saveCapture()}}
async function openIdea(id:string){try{if(!ideas.value.length)ideas.value=(await api.listIdeas({pageSize:100})).items;detail.value=await api.getIdea(id);detailTagsText.value=detail.value.idea.tags.join(', ');detailVisible.value=true;if(route.name!=='creative-detail')router.replace(`/creative/ideas/${id}`)}catch(e){ElMessage.error(e instanceof Error?e.message:'加载失败')}}
function clearDetail(){detail.value=undefined;if(route.name==='creative-detail')router.replace('/creative/ideas')}
async function saveDetail(){if(!detail.value)return;saving.value=true;try{const x=detail.value.idea;await api.updateIdea(x.id,{title:x.title,description:x.description,ideaType:x.ideaType,priority:x.priority,starred:x.starred,parentId:x.parentId||null,visibility:x.visibility,nextAction:x.nextAction,plannedAt:x.plannedAt||null,reviewAt:x.reviewAt||null,conclusion:x.conclusion,pauseReason:x.pauseReason,tagNames:detailTagsText.value.split(/[,，]/).map((t:string)=>t.trim()).filter(Boolean),version:x.version});ElMessage.success('已保存');detail.value=await api.getIdea(x.id);detailTagsText.value=detail.value.idea.tags.join(', ');await loadIdeas();availableTags.value=await api.listTags()}catch(e){ElMessage.error(e instanceof Error?e.message:'保存失败')}finally{saving.value=false}}
async function archiveCurrent(){if(!detail.value)return;try{await ElMessageBox.confirm('归档后会从日常工作区收起，仍可恢复。','归档创意');await api.archiveIdea(detail.value.idea.id);detailVisible.value=false;ElMessage.success('已归档');await load()}catch{}}
async function removeCurrent(){if(!detail.value)return;try{await ElMessageBox.confirm('创意将移入回收站；存在未删除子创意时无法删除。','删除创意',{type:'warning'});await api.deleteIdea(detail.value.idea.id);detailVisible.value=false;ElMessage.success('已移入回收站');await load()}catch(e){if(e!== 'cancel'&&e!=='close')ElMessage.error(e instanceof Error?e.message:'删除失败')}}
async function savePractice(){if(!detail.value)return;saving.value=true;try{const practiceData={...practiceForm,resultLinks:practiceForm.resultUrl?[{url:practiceForm.resultUrl}]:[]};delete (practiceData as any).resultUrl;if(editingPracticeId.value) await api.updatePractice(editingPracticeId.value,{...practiceData,version:detail.value.practices.find(p=>p.id===editingPracticeId.value)?.version});else await api.addPractice(detail.value.idea.id,{...practiceData,version:detail.value.idea.version});editingPracticeId.value=undefined;practiceVisible.value=false;Object.assign(practiceForm,{title:'',action:'',expectation:'',result:'',decision:'',nextAction:'',minutes:undefined,cost:undefined,resultUrl:'',metrics:[],updateNextAction:false});detail.value=await api.getIdea(detail.value.idea.id);detailTagsText.value=detail.value.idea.tags.join(', ');ElMessage.success('实践已记录')}catch(e){ElMessage.error(e instanceof Error?e.message:'保存失败')}finally{saving.value=false}}
async function editPractice(p:api.Practice){editingPracticeId.value=p.id;Object.assign(practiceForm,{kind:p.kind,title:p.title,action:p.action,expectation:p.expectation,result:p.result,decision:p.decision,nextAction:p.nextAction,minutes:p.minutes??undefined,cost:p.cost??undefined,resultUrl:String(p.resultLinks?.[0]?.url||''),metrics:p.metrics.map(m=>({name:String(m.name||''),value:Number(m.value||0),unit:String(m.unit||'')})),updateNextAction:false});practiceVisible.value=true}
async function removePractice(id:string){if(!detail.value)return;try{await ElMessageBox.confirm('删除这条实践记录？','删除实践');await api.deletePractice(id);detail.value=await api.getIdea(detail.value.idea.id);ElMessage.success('实践已删除')}catch(e){if(e!=='cancel')ElMessage.error(e instanceof Error?e.message:'删除失败')}}
async function unlinkMaterial(id:string){if(!detail.value)return;try{await api.unlinkMaterial(detail.value.idea.id,id);detail.value=await api.getIdea(detail.value.idea.id);ElMessage.success('已解除关联')}catch(e){ElMessage.error(e instanceof Error?e.message:'操作失败')}}
async function unlinkRelation(id:string){if(!detail.value)return;try{await api.unrelate(detail.value.idea.id,id);detail.value=await api.getIdea(detail.value.idea.id);ElMessage.success('已解除关联')}catch(e){ElMessage.error(e instanceof Error?e.message:'操作失败')}}
function openEditMaterial(m:Material){editingMaterialId.value=m.id;Object.assign(materialForm,{kind:m.kind,title:m.title,sourceName:m.sourceName,author:m.author,url:m.url,excerpt:m.excerpt,insight:m.insight,visibility:m.visibility,version:m.version});showMaterialForm.value=true}
async function saveMaterial(){saving.value=true;try{if(editingMaterialId.value)await api.updateMaterial(editingMaterialId.value,materialForm);else await api.createMaterial(materialForm);showMaterialForm.value=false;editingMaterialId.value=undefined;Object.assign(materialForm,{title:'',sourceName:'',url:'',excerpt:'',insight:'',version:1});await loadMaterials();ElMessage.success('物料已保存')}catch(e){ElMessage.error(e instanceof Error?e.message:'保存失败')}finally{saving.value=false}}
async function openLinkMaterial(){await loadMaterials();linkVisible.value=true}
async function linkSelected(){if(!detail.value||!selectedMaterial.value)return;try{await api.linkMaterial(detail.value.idea.id,selectedMaterial.value);detail.value=await api.getIdea(detail.value.idea.id);linkVisible.value=false;ElMessage.success('关联成功')}catch(e){ElMessage.error(e instanceof Error?e.message:'关联失败')}}
async function restore(id:string){try{await api.restoreIdea(id);recycle.value=await api.recycleBin();ElMessage.success('已恢复')}catch(e){ElMessage.error(e instanceof Error?e.message:'恢复失败')}}
async function relateCurrent(){await loadIdeas();selectedIdea.value='';linkIdeaVisible.value=true}
const linkIdeaVisible=ref(false)
async function confirmRelation(){if(!detail.value||!selectedIdea.value)return;try{const http=await import('@/api/http');await http.default.post(`/admin/creative/ideas/${detail.value.idea.id}/relations/${selectedIdea.value}`);detail.value=await api.getIdea(detail.value.idea.id);linkIdeaVisible.value=false;ElMessage.success('关联成功')}catch(e){ElMessage.error(e instanceof Error?e.message:'关联失败')}}
async function changeStatus(status:string){if(!detail.value)return;try{let reason='';if(status==='paused'){const res=await ElMessageBox.prompt('请说明暂时搁置的原因','搁置创意');reason=res.value}await api.transition(detail.value.idea.id,status as IdeaStatus,reason,detail.value.idea.version);detail.value=await api.getIdea(detail.value.idea.id);await loadIdeas()}catch(e){detail.value=await api.getIdea(detail.value.idea.id);if(e!=='cancel'&&e!=='close')ElMessage.error(e instanceof Error?e.message:'状态更新失败')}}
async function unarchiveCurrent(){if(!detail.value)return;try{await api.unarchiveIdea(detail.value.idea.id);detail.value=await api.getIdea(detail.value.idea.id);ElMessage.success('已恢复')}catch(e){ElMessage.error(e instanceof Error?e.message:'恢复失败')}}
async function exportCurrent(){if(!detail.value)return;try{const file=await api.exportIdea(detail.value.idea.id);const blob=new Blob([file.content],{type:'text/markdown;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=file.filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}catch(e){ElMessage.error(e instanceof Error?e.message:'导出失败')}}
async function removeMaterial(id:string){try{await ElMessageBox.confirm('物料将移入回收站，关联记录会保留。','移入回收站');await api.deleteMaterial(id);await loadMaterials();ElMessage.success('已移入回收站')}catch(e){if(e!=='cancel')ElMessage.error(e instanceof Error?e.message:'操作失败')}}
async function restoreMaterialItem(id:string){try{await api.restoreMaterial(id);recycle.value=await api.recycleBin();ElMessage.success('已恢复')}catch(e){ElMessage.error(e instanceof Error?e.message:'恢复失败')}}
async function uploadMaterial(id:string,file:File){try{await api.uploadAttachment(id,file);await loadMaterials();ElMessage.success('附件上传成功')}catch(e){ElMessage.error(e instanceof Error?e.message:'上传失败')}}
async function removeAttachment(id:string){try{await ElMessageBox.confirm('移除该附件？','移除附件');await api.deleteAttachment(id);if(detail.value)detail.value=await api.getIdea(detail.value.idea.id);await loadMaterials();ElMessage.success('附件已移除')}catch(e){if(e!=='cancel')ElMessage.error(e instanceof Error?e.message:'移除失败')}}
watch(()=>[query.q,query.status,query.ideaType,query.tag,query.starred,query.archived,query.page,query.pageSize],()=>{if(!isIdeas.value)return;const queryParams:Record<string,string>={};if(query.q)queryParams.q=query.q;if(query.status)queryParams.status=query.status;if(query.ideaType)queryParams.ideaType=query.ideaType;if(query.tag)queryParams.tag=query.tag;if(query.starred)queryParams.starred='true';if(query.archived)queryParams.archived='true';if(query.page>1)queryParams.page=String(query.page);if(query.pageSize!==20)queryParams.pageSize=String(query.pageSize);router.replace({path:'/creative/ideas',query:queryParams})},{deep:true})
watch(()=>route.fullPath,()=>{query.q=String(route.query.q||'');query.status=String(route.query.status||'');query.ideaType=String(route.query.ideaType||'');query.tag=String(route.query.tag||'');query.page=Number(route.query.page||1);query.pageSize=Number(route.query.pageSize||20);query.archived=route.query.archived==='true';query.starred=route.query.starred==='true';if(route.params.id){openIdea(String(route.params.id))}else if(detailVisible.value){detailVisible.value=false}else load()})
onMounted(load)
</script>
