@media(max-width:760px){.metric-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.dashboard-grid{grid-template-columns:1fr}.filters{flex-wrap:wrap}.filters>.el-input{max-width:none;width:100%}.detail-actions{flex-wrap:wrap}.metric-line{flex-wrap:wrap}}
